  const last = readApproval(computerRoot, approvalId);
  if (!last) {
    throw new Error(`approval ${approvalId} missing`);
  }
  if (last.status !== "pending") {
    return last;
  }
  return resolveApproval(computerRoot, approvalId, false);
}

