==== cfo/extensions/intercept.ts
/**
 * Client intercept for consequential Kernel ops.
 * Harness Operator approval is not the queue. Verifier Bots are.
 * Unlock reads the same Handle file completeTurn writes.
 */

import {existsSync, mkdirSync, readdirSync, readFileSync, renameSync, writeFileSync} from "node:fs";
import {dirname, join} from "node:path";

import {isRecord} from "./load.ts";
import {botIdForSlug} from "./profile.ts";
import type {BoundProfile, CatalogOp, VerifierRoute} from "./types.ts";
import {isConsequentialKernelOp, routeVerifier} from "./verifier.ts";

export const VERIFIER_SLUGS: ReadonlySet<string> = new Set(["ctl-pay", "ctl-cash", "ctl-books"]);

export type ConsequentialGate =
  | {readonly kind: "proceed"}
  | {readonly kind: "forbidden"}
  | {readonly kind: "intercept"; readonly route: VerifierRoute};

export type HandleConcurrence = "CONCUR" | "REFUSE" | "none";

function writeJsonAtomic(path: string, value: unknown): void {
  mkdirSync(dirname(path), {recursive: true});
  const tmp = `${path}.tmp.${process.pid}`;
  writeFileSync(tmp, `${JSON.stringify(value, null, 2)}\n`, "utf8");
  renameSync(tmp, path);
}

/** Same path as Harness `handlePath` / completeTurn. */
export function harnessHandlePath(computerRoot: string, botId: string, handleId: string): string {
  return join(computerRoot, "harness", "bots", botId, "handles", `${handleId}.json`);
}

export function pendingIndexPath(computerRoot: string, handleId: string): string {
  return join(computerRoot, "workspace", "verifier", "pending", `${handleId}.json`);
}

/** Legacy Client-only CONCUR store. Not the unlock source of truth. */
export function clientConcurPath(computerRoot: string, handleId: string): string {
  return join(computerRoot, "workspace", "verifier", "handles", `${handleId}.json`);
}

export function findHarnessHandlePath(computerRoot: string, handleId: string): string | undefined {
  const root = join(computerRoot, "harness", "bots");
  if (!existsSync(root)) {
    return undefined;
  }
  for (const ent of readdirSync(root, {withFileTypes: true})) {
    if (!ent.isDirectory()) {
      continue;
    }
    const path = harnessHandlePath(computerRoot, ent.name, handleId);
    if (existsSync(path)) {
      return path;
    }
  }
  return undefined;
}

export function handleConcurrence(result: string): HandleConcurrence {
  const trimmed = result.trim();
  if (trimmed.length === 0) {
    return "none";
  }
  const firstLine = trimmed.split("\n", 1)[0]?.trim().toUpperCase() ?? "";
  if (firstLine === "CONCUR" || firstLine.startsWith("CONCUR")) {
    return "CONCUR";
  }
  if (firstLine === "REFUSE" || firstLine.startsWith("REFUSE")) {
    return "REFUSE";
  }
  const hasConcur = /\bCONCUR\b/i.test(trimmed);
  const hasRefuse = /\bREFUSE\b/i.test(trimmed);
  if (hasConcur && !hasRefuse) {
    return "CONCUR";
  }
  if (hasRefuse && !hasConcur) {
    return "REFUSE";
  }
  return "none";
}

function pendingOpMatches(computerRoot: string, handleId: string, opId: string): boolean {
  const path = pendingIndexPath(computerRoot, handleId);
  if (!existsSync(path)) {
    return true;
  }
  try {
    const raw: unknown = JSON.parse(readFileSync(path, "utf8"));
    if (!isRecord(raw) || typeof raw.op !== "string") {
      return true;
    }
    return raw.op === opId;
  } catch {
    return true;
  }
}

export function completedHandleAllowsOp(
  computerRoot: string,
  handleId: string | null,
  op: CatalogOp,
): boolean {
  if (!handleId) {
    return false;
  }
  const path = findHarnessHandlePath(computerRoot, handleId);
  if (!path) {
    return false;
  }
  try {
    const raw: unknown = JSON.parse(readFileSync(path, "utf8"));
    if (!isRecord(raw) || raw.status !== "completed") {
      return false;
    }
    const result = typeof raw.result === "string" ? raw.result : "";
    if (handleConcurrence(result) !== "CONCUR") {
      return false;
    }
    if (typeof raw.op === "string" && raw.op !== op.id) {
      return false;
    }
    return pendingOpMatches(computerRoot, handleId, op.id);
  } catch {
    return false;
  }
}

export function gateConsequentialCall(
  bind: BoundProfile,
  op: CatalogOp,
  handleId: string | null,
): ConsequentialGate {
  if (!isConsequentialKernelOp(op)) {
    return {kind: "proceed"};
  }
  if (VERIFIER_SLUGS.has(bind.slug)) {
    return {kind: "forbidden"};
  }
  if (completedHandleAllowsOp(bind.computerRoot, handleId, op)) {
    return {kind: "proceed"};
  }
  const route = routeVerifier(op);
  if (!route) {
    return {kind: "forbidden"};
  }
  return {kind: "intercept", route};
}

export function persistPendingHandle(input: {
  readonly computerRoot: string;
  readonly handleId: string;
  readonly op: string;
  readonly route: VerifierRoute;
  readonly fromSlug: string;
  readonly packetPath: string;
  readonly createdAt: string;
}): void {
  const botId = botIdForSlug(input.route.slug);
  writeJsonAtomic(pendingIndexPath(input.computerRoot, input.handleId), {
    id: input.handleId,
    status: "accepted",
    done: false,
    op: input.op,
    toSlug: input.route.slug,
    profile: input.route.profile,
    fromSlug: input.fromSlug,
    packetPath: input.packetPath,
    handleStore: "harness",
    handlePath: harnessHandlePath(input.computerRoot, botId, input.handleId),
    humanQueue: false,
    createdAt: input.createdAt,
  });
}

==== cfo/extensions/verifier.ts
import type {CatalogOp, VerifierRoute} from "./types.ts";

const ACCRUAL_WRITES = new Set([
  "accrual.tools.create_accrual",
  "accrual.tools.reconcile_accrual_with_invoice",
]);

const PAY_PATTERN = /pay_run|pay-run|write_off|write-off|send_as_user|send-as-user/i;
const LOCK_PATTERN = /period_lock|period-lock|mark_closed|lock_period/i;
const CASH_PATTERN = /cash_apply|post_match|post_fee|sign_off_rec/i;

export function isConsequentialKernelOp(op: CatalogOp): boolean {
  if (ACCRUAL_WRITES.has(op.id)) {
    return true;
  }
  if (op.mutability === "side-effect-external") {
    return true;
  }
  if (PAY_PATTERN.test(op.id) || LOCK_PATTERN.test(op.id) || CASH_PATTERN.test(op.id)) {
    return true;
  }
  return false;
}

export function routeVerifier(op: CatalogOp): VerifierRoute | undefined {
  if (ACCRUAL_WRITES.has(op.id)) {
    return {
      slug: "ctl-books",
      profile: "review-treatment",
      reason: "close treatment write",
    };
  }
  if (LOCK_PATTERN.test(op.id)) {
    return {slug: "ctl-books", profile: "lock", reason: "period lock"};
  }
  if (CASH_PATTERN.test(op.id)) {
    return {slug: "ctl-cash", profile: "review-rec", reason: "cash identification"};
  }
  if (PAY_PATTERN.test(op.id) || op.mutability === "side-effect-external") {
    return {slug: "ctl-pay", profile: "review-pay", reason: "money-out or external side effect"};
  }
  return undefined;
}

export interface VerifierIntercept {
  readonly error: "verifier_required";
  readonly verifier: string;
  readonly verifierProfile: string;
  readonly reason: string;
  readonly packetPath: string;
  readonly handleId: string | null;
  readonly instruction: string;
}

export function verifierInstruction(route: VerifierRoute, packetPath: string): string {
  return [
    `profile: ${route.profile}`,
    `Concur or refuse this Kernel op. Packet: ${packetPath}`,
    "First line of the Handle result must be CONCUR or REFUSE.",
    "Do not ask a human. Do not call ask_user. Kernel math still wins.",
  ].join("\n");
}

